tool_input.command:
node --input-type=module -e "
import { backoffDelay } from './src/retry.js';
const N = 200000;
for (const a of [0,1,2,3,6]) {
  let neg=0,min=Infinity,max=-Infinity;
  for (let i=0;i<N;i++){const d=backoffDelay(a); if(d<1)neg++; min=Math.min(min,d); max=Math.max(max,d);}
  console.log('attempt',a,'min',min.toFixed(0),'max',max.toFixed(0),'<1ms',(100*neg/N).toFixed(1)+'%');
}
" && node --test 2>&1 | tail -8
